import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { getCarById, updateCarById } from "../../services/ApiCar";

export default function UpdateVoiture() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [car, setCar] = useState({
    model: "",
    matricule: "",
    prix: ""
  });

  useEffect(() => {
    const fetchCar = async () => {
      try {
        const res = await getCarById(id);
        setCar(res.data);
      } catch (err) {
        console.error("Erreur lors de la récupération de la voiture :", err);
      }
    };
    fetchCar();
  }, [id]);

  const handleChange = (e) => {
    setCar({ ...car, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await updateCarById(id, car);
      alert("Voiture mise à jour avec succès !");
      navigate("/admin/voitures"); // redirige vers la liste des voitures
    } catch (err) {
      console.error("Erreur lors de la mise à jour :", err);
    }
  };

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-100">
      <form onSubmit={handleSubmit} className="bg-white p-8 rounded shadow-md w-full max-w-md">
        <h2 className="text-2xl font-bold mb-6 text-center text-gray-700">Modifier Voiture</h2>

        <div className="mb-4">
          <label className="block text-gray-600 text-sm mb-2">Modèle</label>
          <input
            type="text"
            name="model"
            value={car.model}
            onChange={handleChange}
            required
            className="w-full px-3 py-2 border rounded shadow-sm focus:outline-none focus:ring focus:ring-blue-300"
          />
        </div>

        <div className="mb-4">
          <label className="block text-gray-600 text-sm mb-2">Matricule</label>
          <input
            type="text"
            name="matricule"
            value={car.matricule}
            onChange={handleChange}
            required
            className="w-full px-3 py-2 border rounded shadow-sm focus:outline-none focus:ring focus:ring-blue-300"
          />
        </div>

        <div className="mb-6">
          <label className="block text-gray-600 text-sm mb-2">Prix</label>
          <input
            type="number"
            name="prix"
            value={car.prix}
            onChange={handleChange}
            required
            className="w-full px-3 py-2 border rounded shadow-sm focus:outline-none focus:ring focus:ring-blue-300"
          />
        </div>

        <div className="flex justify-between">
          <button
            type="submit"
            className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-4 rounded shadow"
          >
            ✅ Enregistrer
          </button>
          <button
            type="button"
            onClick={() => navigate("/admin/voitures")}
            className="bg-gray-400 hover:bg-gray-500 text-white font-semibold py-2 px-4 rounded shadow"
          >
            🔙 Annuler
          </button>
        </div>
      </form>
    </div>
  );
}
